def gen(rng):
    def fmt(qs):
        return str(len(qs)) + "\n" + "\n".join(f"{n} {m} {c}" for n, m, c in qs)

    tests = [fmt([(4, 4, 2)]), fmt([(2, 3, 1), (3, 3, 2), (4, 3, 2)]), fmt([(1, 1, 0)]), fmt([(1, 5, 0), (1, 5, 1)]),
             fmt([(3, 1, 0), (3, 1, 1)]), fmt([(5, 5, 4), (5, 5, 5), (5, 5, 0)]),
             fmt([(6, 3, 0), (6, 3, 1), (6, 3, 2), (6, 3, 3)]), fmt([(2, 2, 1)])]
    for _ in range(30):
        qs = []
        for _ in range(rng.randint(1, 6)):
            while True:
                n = rng.randint(1, 7)
                m = rng.randint(1, 6)
                if m ** n <= 20000:
                    break
            qs.append((n, m, rng.randint(0, min(n, m))))
        tests.append(fmt(qs))
    N = 60
    for _ in range(2):
        tests.append(fmt([(rng.randint(1, N), rng.randint(1, N), rng.randint(0, N)) for _ in range(1000)]))
    tests.append(fmt([(rng.randint(50, N), rng.randint(50, N), rng.randint(0, N)) for _ in range(100000)]))
    tests.append(fmt([(N, N, rng.randint(0, 59)) for _ in range(100000)]))
    tests.append(fmt([(N, N, c) for c in range(0, N + 1)] * 20))
    tests.append(fmt([(rng.randint(1, N), rng.randint(1, N), rng.randint(0, 12)) for _ in range(100000)]))
    return tests
